package io.ace;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.MessageDigest;
import java.util.HexFormat;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.Test;

/**
 * The Java SDK writes exactly the bytes of the committed 0.6.1 golden file
 * ({@code examples/golden/0.6.1/GOLDEN.json}): the inputs are regenerated by {@code ace-corpus}
 * and checked against their digests first.
 */
class GoldenTest {
    private static final long WORKLOAD_BYTES = 1024 * 1024;

    private static String sha256(byte[] bytes) throws Exception {
        return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));
    }

    @SuppressWarnings("unchecked")
    private static List<Map<String, Object>> entries() throws IOException {
        Path root = Path.of(System.getProperty("ace.repo.root"));
        String text = Files.readString(root.resolve("examples/golden/0.6.1/GOLDEN.json"));
        Map<String, Object> document = Json.parseObject(text);
        assertEquals(WORKLOAD_BYTES, ((Number) document.get("bytes_per_workload")).longValue());
        return (List<Map<String, Object>>) document.get("entries");
    }

    private static byte[] generate(String workload) throws Exception {
        String binary = System.getProperty("ace.corpus.bin");
        assertTrue(binary != null && Files.isExecutable(Path.of(binary)),
                "ace.corpus.bin must name the ace-corpus binary (cargo build --release -p ace-corpus), got " + binary);
        Path file = Files.createTempFile("ace-golden-", ".bin");
        try {
            Process process = new ProcessBuilder(binary, workload, Long.toString(WORKLOAD_BYTES), file.toString())
                    .redirectErrorStream(true)
                    .start();
            String output = new String(process.getInputStream().readAllBytes());
            assertEquals(0, process.waitFor(), output);
            return Files.readAllBytes(file);
        } finally {
            Files.deleteIfExists(file);
        }
    }

    private static Profile profile(String name) {
        return switch (name) {
            case "fast" -> Profile.FAST;
            case "balanced" -> Profile.BALANCED;
            case "dense" -> Profile.DENSE;
            default -> throw new IllegalArgumentException(name);
        };
    }

    @Test
    @SuppressWarnings("unchecked")
    void reproducesTheGoldenFileForEveryWorkloadAndProfile() throws Exception {
        List<Map<String, Object>> entries = entries();
        assertEquals(31, entries.size());
        for (Map<String, Object> entry : entries) {
            String workload = (String) entry.get("workload");
            byte[] input = generate(workload);
            assertEquals(entry.get("input_sha256"), sha256(input), workload + " input");
            for (Map<String, Object> expected : (List<Map<String, Object>>) entry.get("profiles")) {
                String name = (String) expected.get("profile");
                try (Engine engine = Engine.create(Config.builder().profile(profile(name)).build())) {
                    byte[] packed = engine.compress(input);
                    String label = workload + " " + name;
                    assertEquals(((Number) expected.get("ace_bytes")).longValue(), packed.length, label);
                    assertEquals(expected.get("ace_sha256"), sha256(packed), label);
                    assertArrayEquals(input, engine.decompress(packed), label);
                }
            }
        }
    }

    @Test
    @SuppressWarnings("unchecked")
    void theBytesDoNotDependOnTheThreadCount() throws Exception {
        Map<String, Object> entry = entries().stream()
                .filter(e -> "low-cardinality".equals(e.get("workload")))
                .findFirst()
                .orElseThrow();
        Map<String, Object> balanced = ((List<Map<String, Object>>) entry.get("profiles")).stream()
                .filter(p -> "balanced".equals(p.get("profile")))
                .findFirst()
                .orElseThrow();
        byte[] input = generate("low-cardinality");
        for (int threads : new int[] {1, 2, 3, 8}) {
            try (Engine engine = Engine.create(Config.builder().threads(threads).build())) {
                assertEquals(balanced.get("ace_sha256"), sha256(engine.compress(input)), threads + " threads");
            }
        }
    }
}
